import{_ as a,b as n,f as l,I as e}from"./chunks/framework.DYvp_Vyw.js";const u=JSON.parse('{"title":"数据库技术与原理 - 期末考后感想","description":"","frontmatter":{"title":"数据库技术与原理 - 期末考后感想","date":"2025-05-27T11:14:28.000Z","tags":["数据库","SqlServer"],"head":[["meta",{"name":"descriptionx x x","content":"vitepress-theme-bluearchive Tags"}],["meta",{"name":"keywords","content":"vitepress theme bluearchive Tags"}]]},"headers":[],"relativePath":"posts/SqlServer-Final-Summary.md","filePath":"posts/SqlServer-Final-Summary.md"}'),p={name:"posts/SqlServer-Final-Summary.md"};function o(r,s,c,t,i,y){return l(),n("div",null,s[0]||(s[0]=[e(`<p>啊啊啊啊...狗蛋的学校编译器坑我6分大题....</p><hr><h1 id="关于本次期末考试" tabindex="-1">关于本次期末考试 <a class="header-anchor" href="#关于本次期末考试" aria-label="Permalink to &quot;关于本次期末考试&quot;">​</a></h1><p>关于期末考试，感觉难度差差不多就那样，中规中矩，但是，我还是被坑了两道编程题....<br> 这次的大题考察了两个平时实验报告没有的题型，分别是：</p><ul><li>怎么通过SQL代码创建新表，然后新表的数据来源是数据库中的已有表。</li><li>要求在指定的两列之间插入一个新列。</li></ul><p>第一个问题其实不难，有以下方法：</p><h2 id="第一种" tabindex="-1">第一种 <a class="header-anchor" href="#第一种" aria-label="Permalink to &quot;第一种&quot;">​</a></h2><div class="language-sql line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki solarized-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#586E75;font-style:italic;">-- 创建新表并复制数据（结构+数据）</span></span>
<span class="line"><span style="color:#859900;">SELECT</span><span style="color:#859900;"> *</span></span>
<span class="line"><span style="color:#859900;">INTO</span><span style="color:#839496;"> 新表名</span></span>
<span class="line"><span style="color:#859900;">FROM</span><span style="color:#839496;"> 已有表名</span></span>
<span class="line"><span style="color:#839496;">[WHERE 条件];</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><h2 id="第二种-带条件创建-oracle-postgresql语法" tabindex="-1">第二种 带条件创建（Oracle/PostgreSQL语法） <a class="header-anchor" href="#第二种-带条件创建-oracle-postgresql语法" aria-label="Permalink to &quot;第二种 带条件创建（Oracle/PostgreSQL语法）&quot;">​</a></h2><div class="language-sql line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki solarized-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#586E75;font-style:italic;">-- 创建表时直接筛选数据（Oracle/PostgreSQL）</span></span>
<span class="line"><span style="color:#859900;">CREATE</span><span style="color:#859900;"> TABLE</span><span style="color:#268BD2;"> 新表名</span><span style="color:#859900;"> AS</span></span>
<span class="line"><span style="color:#859900;">SELECT</span><span style="color:#839496;"> 列1, 列2 </span></span>
<span class="line"><span style="color:#859900;">FROM</span><span style="color:#839496;"> 已有表名</span></span>
<span class="line"><span style="color:#859900;">WHERE</span><span style="color:#839496;"> 条件;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#586E75;font-style:italic;">-- 示例：创建高薪员工表</span></span>
<span class="line"><span style="color:#859900;">CREATE</span><span style="color:#859900;"> TABLE</span><span style="color:#268BD2;"> high_salary_employees</span><span style="color:#859900;"> AS</span></span>
<span class="line"><span style="color:#859900;">SELECT</span><span style="color:#839496;"> employee_id, </span><span style="color:#859900;">name</span><span style="color:#839496;">, salary</span></span>
<span class="line"><span style="color:#859900;">FROM</span><span style="color:#839496;"> employees</span></span>
<span class="line"><span style="color:#859900;">WHERE</span><span style="color:#839496;"> salary </span><span style="color:#859900;">&gt;</span><span style="color:#D33682;"> 10000</span><span style="color:#839496;">;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div><h2 id="第三种-create-table-insert-分步操作" tabindex="-1">第三种 CREATE TABLE + INSERT（分步操作） <a class="header-anchor" href="#第三种-create-table-insert-分步操作" aria-label="Permalink to &quot;第三种 CREATE TABLE + INSERT（分步操作）&quot;">​</a></h2><div class="language-sql line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki solarized-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#586E75;font-style:italic;">-- 步骤1：创建空表（复制结构）</span></span>
<span class="line"><span style="color:#859900;">CREATE</span><span style="color:#859900;"> TABLE</span><span style="color:#268BD2;"> 新表名</span><span style="color:#859900;"> AS</span></span>
<span class="line"><span style="color:#859900;">SELECT</span><span style="color:#859900;"> *</span><span style="color:#859900;"> FROM</span><span style="color:#839496;"> 已有表名</span></span>
<span class="line"><span style="color:#859900;">WHERE</span><span style="color:#D33682;"> 1</span><span style="color:#859900;">=</span><span style="color:#D33682;">0</span><span style="color:#839496;">;  </span><span style="color:#586E75;font-style:italic;">-- 只复制结构不复制数据</span></span>
<span class="line"></span>
<span class="line"><span style="color:#586E75;font-style:italic;">-- 步骤2：插入数据</span></span>
<span class="line"><span style="color:#859900;">INSERT INTO</span><span style="color:#839496;"> 新表名</span></span>
<span class="line"><span style="color:#859900;">SELECT</span><span style="color:#859900;"> *</span><span style="color:#859900;"> FROM</span><span style="color:#839496;"> 已有表名</span></span>
<span class="line"><span style="color:#839496;">[WHERE 条件];</span></span>
<span class="line"></span>
<span class="line"><span style="color:#586E75;font-style:italic;">-- 示例：创建销售部门员工表</span></span>
<span class="line"><span style="color:#859900;">CREATE</span><span style="color:#859900;"> TABLE</span><span style="color:#268BD2;"> sales_employees</span><span style="color:#859900;"> AS</span></span>
<span class="line"><span style="color:#859900;">SELECT</span><span style="color:#859900;"> *</span><span style="color:#859900;"> FROM</span><span style="color:#839496;"> employees </span><span style="color:#859900;">WHERE</span><span style="color:#D33682;"> 1</span><span style="color:#859900;">=</span><span style="color:#D33682;">0</span><span style="color:#839496;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#859900;">INSERT INTO</span><span style="color:#839496;"> sales_employees</span></span>
<span class="line"><span style="color:#859900;">SELECT</span><span style="color:#859900;"> *</span><span style="color:#859900;"> FROM</span><span style="color:#839496;"> employees </span></span>
<span class="line"><span style="color:#859900;">WHERE</span><span style="color:#839496;"> department </span><span style="color:#859900;">=</span><span style="color:#2AA198;"> &#39;Sales&#39;</span><span style="color:#839496;">;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br></div></div><h2 id="第四种-复制表结构-部分数据-sql-server" tabindex="-1">第四种 复制表结构+部分数据（SQL Server） <a class="header-anchor" href="#第四种-复制表结构-部分数据-sql-server" aria-label="Permalink to &quot;第四种 复制表结构+部分数据（SQL Server）&quot;">​</a></h2><div class="language-sql line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki solarized-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#586E75;font-style:italic;">-- 使用WHERE 1=0只复制结构</span></span>
<span class="line"><span style="color:#859900;">SELECT</span><span style="color:#859900;"> *</span><span style="color:#839496;"> </span></span>
<span class="line"><span style="color:#859900;">INTO</span><span style="color:#839496;"> 新表名</span></span>
<span class="line"><span style="color:#859900;">FROM</span><span style="color:#839496;"> 已有表名</span></span>
<span class="line"><span style="color:#859900;">WHERE</span><span style="color:#D33682;"> 1</span><span style="color:#859900;">=</span><span style="color:#D33682;">0</span><span style="color:#839496;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#586E75;font-style:italic;">-- 再插入需要的数据</span></span>
<span class="line"><span style="color:#859900;">INSERT INTO</span><span style="color:#839496;"> 新表名</span></span>
<span class="line"><span style="color:#859900;">SELECT</span><span style="color:#859900;"> *</span><span style="color:#859900;"> FROM</span><span style="color:#839496;"> 已有表名</span></span>
<span class="line"><span style="color:#859900;">WHERE</span><span style="color:#839496;"> salary </span><span style="color:#859900;">&gt;</span><span style="color:#D33682;"> 5000</span><span style="color:#839496;">;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br></div></div><blockquote><p>其实第一种和第二种方法我想到了，第一种想到的不完全，只想到了一个into，所以当时代码并没有完全敲出来。<br> 但是第二种方法，我完整的敲出来了，但是学校的编译器不知道为什么在 as 那里给我标红了，我当时以为错了，就没运行了😭</p></blockquote><hr><p>然后第二个问题，就是要求在指定的两列之间插入一个新列。 代码：</p><div class="language-sql line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki solarized-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#859900;">ALTER</span><span style="color:#859900;"> TABLE</span><span style="color:#839496;"> 表名</span></span>
<span class="line"><span style="color:#859900;">ADD</span><span style="color:#839496;"> 新列名 数据类型 </span></span>
<span class="line"><span style="color:#839496;">[约束条件] </span></span>
<span class="line"><span style="color:#859900;">AFTER</span><span style="color:#839496;"> 指定列名;  </span><span style="color:#586E75;font-style:italic;">-- 在指定列后插入</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><blockquote><p>这个我当时也想到了，但是不知道为什么，在指定列名那里编译器给我爆红了😭</p></blockquote><hr><h1 id="总结感慨" tabindex="-1">总结感慨 <a class="header-anchor" href="#总结感慨" aria-label="Permalink to &quot;总结感慨&quot;">​</a></h1><p>反正就挺无语的吧，两道题，都想到正确思路了，但是因为编译器爆红我就没运行了。罢了，反正不挂科，但是想要上90很难了，有点小悲伤。</p><hr>`,23)]))}const d=a(p,[["render",o]]);export{u as __pageData,d as default};
